using System.Linq;using System.Text;using UnityEditor;using UnityEngine;using UnityEngine.Profiling;
namespace XuanwuTools { public static class PerformanceAuditor {
 [MenuItem(Common.Menu+"10 Performance inventory")] public static void Audit()=>Common.Run(()=>{var rs=Common.SceneObjects<Renderer>().ToArray();var mats=rs.SelectMany(r=>r.sharedMaterials).Where(m=>m).Distinct().ToArray();var tex=mats.SelectMany(m=>m.GetTexturePropertyNames().Select(m.GetTexture)).Where(t=>t).Distinct().ToArray();long bytes=tex.Sum(t=>Profiler.GetRuntimeMemorySizeLong(t));long tris=0;foreach(var f in Common.SceneObjects<MeshFilter>()){var m=f.sharedMesh;if(!m)continue;for(int i=0;i<m.subMeshCount;i++)if(m.GetTopology(i)==MeshTopology.Triangles)tris+=(long)m.GetIndexCount(i)/3;}Common.Report("performance-inventory",$"renderers={rs.Length}\nunique materials={mats.Length}\ntexture objects={tex.Length}\ntexture runtime estimate bytes={bytes}\nmesh instance triangles incl all LODs={tris}\nNOT visible triangles, draw calls, GPU frame time, or build memory. Capture Profiler in player with fixed camera/resolution.");});}}
